method below_zero(operations: seq<int>) returns (result: (seq<int>, bool))
  ensures |result.0| == |operations| + 1
  ensures result.0[0] == 0
  ensures forall i :: 0 <= i < |result.0| - 1 ==> result.0[i + 1] == result.0[i] + operations[i]
  ensures result.1 ==> HasNegativeFrom(result.0, 1)
  ensures !result.1 ==> forall i :: 0 <= i < |result.0| ==> result.0[i] >= 0
{
  var s: seq<int> := [0];
  var i := 0;
  while i < |operations|
    invariant 0 <= i <= |operations|
    invariant |s| == i + 1
    invariant s[0] == 0
    invariant forall k :: 0 <= k < i ==> s[k + 1] == s[k] + operations[k]
  {
    s := s + [s[i] + operations[i]];
    i := i + 1;
  }
  var neg := false;
  var k := 0;
  while k < |s|
    invariant 0 <= k <= |s|
    invariant forall m :: 0 <= m < k ==> s[m] >= 0
  {
    if s[k] < 0 {
      NegativeOccurs(s, k, 1);
      neg := true;
      break;
    }
    k := k + 1;
  }
  result := (s, neg);
}

lemma NegativeOccurs(s: seq<int>, k: nat, i: nat)
  requires i <= k < |s| && s[k] < 0
  ensures HasNegativeFrom(s, i)
  decreases k - i
{
  if i < k {
    NegativeOccurs(s, k, i + 1);
  }
}

