import icontract
from typing import List, Tuple


@icontract.ensure(lambda operations, result: len(result[0]) == len(operations) + 1)
@icontract.ensure(lambda result: len(result[0]) > 0 and result[0][0] == 0)
@icontract.ensure(lambda operations, result: len(result[0]) == len(operations) + 1 and all(
    result[0][i + 1] == result[0][i] + operations[i] for i in range(len(result[0]) - 1)))
@icontract.ensure(lambda operations, result: (not result[1]) or (
    len(result[0]) == len(operations) + 1 and any(result[0][i + 1] < 0 for i in range(len(operations)))))
@icontract.ensure(lambda result: result[1] or all(x >= 0 for x in result[0]))
def below_zero(operations: List[int]) -> Tuple[List[int], bool]:
    s = [0]
    for op in operations:
        s.append(s[-1] + op)
    neg = False
    for x in s:
        if x < 0:
            neg = True
            break
    return (s, neg)
